SELECT a.id, p.titel AS productie, substr(a.start_at, 1, 10) AS datum, substr(a.start_at, 12, 5) AS start, o.naam AS venue, o.adres FROM activiteit a JOIN productie p ON p.id = a.productie_id AND p.deleted_at IS NULL LEFT JOIN organisatie o ON o.id = a.locatie_id AND o.deleted_at IS NULL WHERE a.deleted_at IS NULL AND a.soort = 'voorstelling' AND a.status = 'bevestigd'
